const output = [];

// Safely convert values to text
const str = (v) =>
  typeof v === "string"
    ? v.trim()
    : v == null
      ? ""
      : typeof v === "object"
        ? JSON.stringify(v)
        : String(v);

// Find first non-empty value
const first = (...values) =>
  values.map(str).find(Boolean) || "";

// Extract email
const emailOf = (v) => {
  const match = str(v).match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
  );
  return match ? match[0] : "";
};

// Extract phone number
function phoneOf(v) {
  const text = str(v).replace(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
    " "
  );

  const matches = text.match(
    /(?:\+|00)?\d[\d\s().-]{8,}\d/g
  ) || [];

  for (const match of matches) {
    const phone = match.trim();
    const digits = phone.replace(/\D/g, "");

    if (
      digits.length >= 10 &&
      digits.length <= 15 &&
      !/^\d{4}-\d{2}-\d{2}/.test(phone)
    ) {
      return phone;
    }
  }

  return "";
}

// Find a valid value across multiple sources
function findValue(values, parser) {
  for (const value of values) {
    const result = parser(value);
    if (result) return result;
  }
  return "";
}

for (const item of $input.all()) {
  const p = item.json.body ?? item.json;
  const lead = p.lead ?? {};
  const contact = p.contact ?? {};

  const transcript = Array.isArray(p.transcript)
    ? p.transcript
    : Array.isArray(p.messages)
      ? p.messages
      : [];

  const roleOf = (m) =>
    str(m.role ?? m.sender).toLowerCase();

  const messageOf = (m) =>
    str(m.content ?? m.text ?? m.message);

  const isVisitor = (m) =>
    ["user", "visitor", "human"].includes(roleOf(m));

  const visitors = transcript
    .filter(isVisitor)
    .map(messageOf);

  const newestFirst = [...visitors].reverse();

  // 1. PHONE - HIGHEST CONTACT PRIORITY
  const phone = findValue([
    lead.phone,
    lead.phoneNumber,
    lead.mobile,
    lead.whatsapp,
    contact.phone,
    p.phone,
    p.phoneNumber,
    ...newestFirst
  ], phoneOf);

  // 2. EMAIL
  const email = findValue([
    lead.email,
    lead.emailAddress,
    contact.email,
    p.email,
    ...newestFirst
  ], emailOf);

  // Recover answers given after Invo asks questions
  function answerAfter(pattern) {
    for (let i = transcript.length - 2; i >= 0; i--) {
      const question = transcript[i];
      const reply = transcript[i + 1];

      if (
        !isVisitor(question) &&
        pattern.test(messageOf(question)) &&
        isVisitor(reply)
      ) {
        const answer = messageOf(reply)
          .replace(
            /^(?:my name is|i'm|it's|it is|we're|our business is|our company is)\s+/i,
            ""
          )
          .trim();

        if (
          answer &&
          answer.length <= 90 &&
          !emailOf(answer) &&
          !phoneOf(answer)
        ) {
          return answer;
        }
      }
    }
    return "";
  }

  // 3. NAME
  const name = first(
    lead.name,
    contact.name,
    p.name,
    answerAfter(/\b(?:your name|call you)\b/i)
  );

  // 4. BUSINESS NAME
  const business = first(
    lead.businessName,
    lead.companyName,
    contact.businessName,
    p.businessName,
    answerAfter(
      /\b(?:business called|business name|company name|name of your (?:cleaning )?business)\b/i
    )
  );

  // 5. MAIN CONCERN
  let concern = first(
    lead.description,
    lead.mainConcern,
    p.mainConcern,
    p.description
  );

  // Recover an issue from the conversation
  if (!concern) {
    concern = visitors.find((text) =>
      /\b(miss(?:ed|ing)?|follow[- ]?ups?|quotes?|repeat|reviews?|inquir(?:y|ies)|no[- ]?shows?|schedul(?:e|ing)|bookings?|leads?|jobs?)\b/i.test(text) &&
      !/^\s*(?:what|how|can|do|is|are)\b/i.test(text)
    ) || "";
  }

  // 6. DIRECT BOOKING INTENT
  const firstVisitor = visitors[0] ?? "";

  const askedDirectly =
    p.askedToBookDirectly === true ||
    /\b(?:free\s+(?:business\s+)?audit|book(?:ing)?\s+(?:a\s+)?(?:call|audit)|schedule\s+(?:a\s+)?(?:call|audit)|consultation)\b/i.test(firstVisitor);

  // 7. CONTACT DETAILS
  const contactDetails = [
    phone && `Phone: ${phone}`,
    email && `Email: ${email}`,
    name && `Name: ${name}`,
    business && `Business: ${business}`
  ].filter(Boolean).join("\n");

  // 8. FULL CHAT HISTORY
  const chat = transcript.map((m) => {
    const role = roleOf(m);

    const speaker = isVisitor(m)
      ? "Visitor"
      : ["assistant", "ai"].includes(role)
        ? "Invo"
        : role || "Unknown";

    return `${speaker}: ${messageOf(m)}`;
  }).join("\n");

  // 9. SESSION ID
  const sessionId = first(
    p.sessionId,
    p.session_id
  );

  if (!sessionId) {
    throw new Error(
      "Missing Session ID. Cannot safely update chat row."
    );
  }

  // 10. LEAD CAPTURE STATUS
  // Phone required to count as a captured lead
  const captured = Boolean(phone);

  // FINAL GOOGLE SHEETS OUTPUT
  output.push({
    json: {
      "Session ID": sessionId,
      "Last Updated":
        first(p.timestamp, p.updatedAt) ||
        new Date().toISOString(),

      "Contact Details": contactDetails,
      "Main Concern": concern,
      "Lead Captured": captured ? "Yes" : "No",
      "Asked To Book Directly":
        askedDirectly ? "Yes" : "No",
      "Chat": chat,

      // Additional individual fields
      "Phone": phone,
      "Email": email,
      "Name": name,
      "Business Name": business
    }
  });
}

return output;

