function contentToHTML(raw, bookingLink, kind) {
  const rows = raw.replace(/\r\n?/g,'\n').split('\n');
  const out=[];
  let bullets=[];let paragraph=[];let added=false;
  const flushP=()=>{if(!paragraph.length)return;let t=paragraph.join('\n').trim();paragraph=[];if(!t)return;
    const isPS=/^P\.S\./i.test(t);
    if(isPS)out.push(`<div style="background:#F7FAFF;padding:14px;border-left:3px solid ${C.blue};margin:15px 0;color:${C.ink};font:13px/21px Arial,sans-serif">${e(t).replace(/\n/g,'<br>')}</div>`);
    else out.push(pTag(t,/^Here's what we'd do first:/i.test(t)?`font-weight:700;color:${C.navy};`:''));
  };
  const flushB=()=>{if(bullets.length){out.push(bulletTable(bullets));bullets=[]}};
  for(let row of rows){const s=row.trim();if(!s){flushP();flushB();continue;}
    const isBullet=/^[-*]\s+/.test(s);
    if(isBullet){flushP();bullets.push(s);continue;}
